import os, sys
from pathlib import Path

root = Path('/testbed')
os.environ.setdefault('MPLBACKEND','Agg')
sys.path.insert(0, str(root / 'lib'))

from matplotlib.mathtext import MathTextParser


def _nested_frac_expr(depth:int)->str:
    if depth <= 0:
        return 'x'
    return r'\\frac{' + _nested_frac_expr(depth-1) + '}{y}'

TARGET = str((root / 'lib' / 'matplotlib').resolve())

stack = []
max_depth = 0
max_snapshot = None

def in_scope(frame):
    fn = frame.f_code.co_filename
    if not fn:
        return False
    try:
        p = str(Path(fn).resolve())
    except Exception:
        return False
    return p.startswith(TARGET + os.sep)


def tracefunc(frame, event, arg):
    global max_depth, max_snapshot
    if event == 'call':
        if in_scope(frame):
            stack.append(frame)
            d = len(stack)
            if d > max_depth:
                max_depth = d
                max_snapshot = [f"{Path(f.f_code.co_filename).name}:{f.f_code.co_name}" for f in stack]
            return tracefunc
        return tracefunc

    if event in ('return','exception'):
        if in_scope(frame):
            if stack and stack[-1] is frame:
                if event == 'return':
                    stack.pop()
            else:
                # Recover if tracing got out of sync due to exceptions/unwinds.
                for i in range(len(stack)-1, -1, -1):
                    if stack[i] is frame:
                        if event == 'return':
                            del stack[i:]
                        break
            return tracefunc
        return tracefunc

    return tracefunc

sys.settrace(tracefunc)
expr = _nested_frac_expr(24)
parser = MathTextParser('path')
parser.parse(expr, dpi=96)
sys.settrace(None)

print('max_depth', max_depth)
print('max_snapshot_tail', max_snapshot[-8:] if max_snapshot else None)
print('remaining_stack', len(stack))
